  const [num, setNum] = useState(0)
  function change() {
    let numbre = num
    numbre = 10
    setNum(numbre)
  }
  return (
    <>

    </>
  );
}

function Elem({content, func}) {
  return <>{content} <button onClick={change}>click</button></>
}


